return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'jv_ID','project-id-version'=>'babilim-0.1.0-jv_ID-babilim-0.1.0-jv_ID-20261030T025553','pot-creation-date'=>'2026-10-30T06:25:31+00:00','po-revision-date'=>'2026-10-30T06:25:31+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Nglengkapi terjemahan sing durung ana kanggo plugin lan tema sing wis dipasang ing situsmu.','Translations'=>'Terjemahan','Babilim Settings'=>'Pangaturan Babilim','Settings'=>'Pangaturan','You are not allowed to do this.'=>'Sampeyan ora diidini nindakake iki.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Pilih komponen sing luwih sithik: paling akeh %1$d operasi saben proses (sampeyan milih %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Komponen kasebut ora dipasang ing situs iki, mula terjemahane ora bisa dijaluk.','Already installed.'=>'Wis dipasang.','Downloaded and installed.'=>'Wis diundhuh lan dipasang.','Babilim has not been enabled for this site yet.'=>'Babilim durung diaktifake kanggo situs iki.','No build is available to download for this locale.'=>'Ora ana build sing bisa diundhuh kanggo lokal iki.','Rolled back to the previous build.'=>'Dibalekake menyang build sakdurunge.','Rolled back and reported.'=>'Dibalekake lan dilaporake.','Rolled back, but the report could not be sent: %s'=>'Dibalekake, nanging laporane ora bisa dikirim: %s','Removed.'=>'Wis dibusak.','Translation requested.'=>'Terjemahan wis dijaluk.','This component was already uploaded. Babilim is checking it now.'=>'Komponen iki wis diunggah. Babilim lagi mriksa saiki.','Upload cancelled.'=>'Unggahan dibatalake.','Upload complete — translation requested.'=>'Unggahan rampung — terjemahan wis dijaluk.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Komponen iki ora nyebutake nomer versi, mula terjemahane ora bisa dijaluk.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Nomer versi komponen iki luwih saka %d karakter, sing ora bisa ditangani Babilim, mula terjemahane ora bisa dijaluk.','A translation cannot be requested for that locale on this site right now.'=>'Terjemahan kanggo lokal kasebut ora bisa dijaluk ing situs iki saiki.','Thank you. Your report was sent.'=>'Matur nuwun. Laporanmu wis dikirim.','This report does not name a valid plugin or theme and locale.'=>'Laporan iki ora nyebutake Jeneng plugin utawa tema lan lokal sing sah.','Please choose a category for this report.'=>'Mangga pilih kategori kanggo laporan iki.','This report is missing a valid build to report against.'=>'Laporan iki ora duwe build sing sah kanggo dilaporake.','This build is not one this site currently knows about for this component/locale.'=>'Build iki dudu build sing saiki dikenal situs iki kanggo komponen/lokal iki.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Kolom "%1$s" dawa banget: isine %2$d karakter lan watese %3$d. Ora ana sing dikirim; mangga cekakake lan coba maneh.','Original string'=>'String asli','String context'=>'Konteks string','Current translation'=>'Terjemahan saiki','Suggested translation'=>'Terjemahan sing disaranake','Note (optional)'=>'Cathetan (opsional)','Where you saw this (optional)'=>'Ing ngendi sampeyan ndeleng iki (opsional)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Sinkronisasi Babilim ditundha sauntara dening layanan (diwatesi lajune); bakal dicoba maneh sawise %s.','The locale you added is not valid: use a WordPress locale code such as ll_CC (letters, digits, underscore, hyphen or @, at most %d characters). Nothing was saved.'=>'Lokal sing sampeyan tambahake ora sah: gunakake kode lokal WordPress kayata ll_CC (aksara, angka, garis ngisor, tanda hubung utawa @, paling akeh %d karakter). Ora ana sing disimpen.','Settings saved.'=>'Pangaturan wis disimpen.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Yen iki diaktifake, nyopot instalasi uga bakal mbusak identitas situs iki. Lisensi mbayar sing ana ing situs iki ora bisa dibalekake kanthi otomatis sawise iku; sampeyan kudu ngubungi Dhukungan Babilim ing %s kanggo njaluk maneh.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim disetel kanggo mbusak identitas situs iki nalika plugin dibusak. Lisensi mbayar sing ana ing situs iki banjur ora bisa dibalekake kanthi otomatis; sampeyan kudu ngubungi Dhukungan Babilim ing %s. Kanggo njaga identitas, pencet Batal, copot centhang "Busak kabeh data Babilim nalika dicopot" ing pangaturan Babilim, banjur nonaktifake maneh. Tetep nonaktifake?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Jaringan iki duwe situs sing kakehan kanggo dipriksa siji-siji, lan sawetara bisa wae disetel kanggo mbusak identitas Babilim nalika plugin dibusak. Lisensi mbayar sing ana ing situs kuwi banjur ora bisa dipulihake kanthi otomatis; sampeyan kudu ngubungi Dhukungan Babilim ing %s. Kanggo njaga identitas kasebut, pencet Batal, copot centhang "Busak kabeh data Babilim nalika dicopot" ing pangaturan Babilim saben situs, lan nonaktifake maneh. Tetep nonaktifake?','Open Babilim settings'=>'Bukak pangaturan Babilim','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim ora bisa verifikasi situs iki, mula ora ana sing diundhuh utawa dipasang.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Layanan ora bisa nyambung menyang situs sampeyan. Firewall, plugin keamanan utawa aturan host kayane ngeblokir panyuwunan; mangga ijinake panyuwunan menyang /wp-json/babilim/v1/challenge.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Situs sampeyan suwe banget anggone mangsuli. Coba maneh mengko, lan priksa manawa host sampeyan ora alon banget utawa kebebanan.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Situs sampeyan mangsuli, nanging ora kaya sing dikarepake. REST API bisa wae ditulis ulang dening plugin liyane, utawa endpoint kuwi di-cache; mangga kecualiake /wp-json/babilim/v1/challenge saka caching lan penulisan ulang.','Please check that your site can be reached from the internet, then try again.'=>'Priksa manawa situs sampeyan bisa diakses saka internet, banjur coba maneh.','Re-verify'=>'Verifikasi maneh','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Situs iki ngluwihi ukuran sing ditampa layanan ing sakali sinkronisasi, mula sawetara item ora kalebu: %1$d komponen lan %2$d lokal.','This site is verified.'=>'Situs iki wis diverifikasi.','Registration restarted.'=>'Registrasi diwiwiti maneh.','Sync complete.'=>'Sinkronisasi rampung.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim lagi ngaktifake lan mriksa situs iki… Muat ulang kaca iki utawa enteni pamriksan terjadwal rampung.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim ora bisa rampung ngaktifake (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Host sing mung nglayani siji panyuwunan PHP ing sawijining wektu ora bisa ngrampungake langkah iki.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim dinonaktifake. Ora ana maneh sing dikirim; terjemahan sing wis dipasang tetep bisa digunakake.','Supplementary translation index rebuilt.'=>'Indeks terjemahan tambahan wis dibangun maneh.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Instalasi otomatis saiki mati; aktifake maneh ing pangaturan yen sampeyan gelem.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim nemokake plugin lan tema ing situs iki sing durung duwe terjemahan kanggo basa sampeyan lan masang siji kanggo saben-saben.','Languages found on this site: %s.'=>'Basa sing ditemokake ing situs iki: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Terjemahan sing kasedhiya bisa dipasang kanthi siji klik, lan sing durung ana bisa dijaluk. Sawise iku, terjemahan anyar lan nganyari dipasang kanthi otomatis (ing paket gratis, mung kanggo plugin lan tema sing wis nggunakake slot gratis).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Paket gratis nyakup plugin lan tema kanthi jumlah winates; kuota sampeyan sing pas ditampilake ing Pangaturan sawise sampeyan ngaktifake Babilim.','What is sent when you enable Babilim'=>'Apa sing dikirim nalika sampeyan ngaktifake Babilim','Enabling…'=>'Ngaktifake…','Enable Babilim'=>'Aktifake Babilim','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Kanthi ngeklik Aktifake, sampeyan setuju ngirim informasi sing kadhaptar ing ndhuwur menyang Babilim.','Check again now'=>'Priksa maneh saiki','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim lagi ngaktifake lan mriksa situs iki… (upaya pungkasan: %s)','Check again'=>'Priksa maneh','No components synced yet.'=>'Durung ana komponen sing disinkronake.','Bulk %s:'=>'Massal %s:','%1$s nothing to do.'=>'%1$s ora ana sing perlu ditindakake.','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Nerusake…','Continue next batch (%d left)'=>'Lanjutake batch sabanjuré (isih %d)','Search components'=>'Golèk komponèn','These are the languages this site uses. You can change them in %s.'=>'Iki basa-basa sing digunakake situs iki. Panjenengan bisa ngowahi ing %s.','Upload this component?'=>'Unggah komponèn iki?','There is no upload waiting for confirmation.'=>'Ora ana unggahan sing nunggu konfirmasi.','Back'=>'Bali','To translate this component, Babilim needs its source.'=>'Kanggo nerjemahake komponèn iki, Babilim butuh sumberé.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'Kabèh direktori plugin utawa tema %1$s (versi %2$s) bakal diunggah menyang Babilim.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Yèn direktori kuwi ngandhut kunci, log, utawa data pelanggan, kuwi uga bakal diunggah. Layanan iki mbusak berkas sensitif umum (konfigurasi, lingkungan, dump database, log, kunci), nanging ora bisa njamin nemokaké kabèh.','The upload is kept until you ask Babilim to delete it.'=>'Unggahan disimpen nganti Panjenengan njaluk Babilim mbusaké.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Iki disimpen déning panyedhia hosting layanan lan diproses model AI kanggo ngasilaké terjemahan.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Teks asli lan terjemahan sing digawé saka kuwi bakal diwènèhaké menyang situs liya sing masang versi sing padha.','By continuing you confirm that you have the right to upload this component.'=>'Kanthi nerusaké, Panjenengan mastèkaké nèk Panjenengan nduwé hak kanggo ngunggah komponèn iki.','Upload and request'=>'Unggah lan njaluk','Uploading…'=>'Lagi ngunggah…','Cancel'=>'Batal','Uploading'=>'Lagi ngunggah','There is no upload in progress.'=>'Ora ana unggahan sing lagi mlaku.','Uploading part %1$d of %2$d…'=>'Lagi ngunggah bagéan %1$d saka %2$d…','Continue'=>'Terusaké','Confirm'=>'Konfirmasi','Remove'=>'Busak','Roll back'=>'Kembalikan','Nothing to confirm.'=>'Ora ana sing dikonfirmasi.','Choose a language'=>'Pilih basa','Roll back and report'=>'Kembalikan lan laporaké','Report a problem'=>'Laporaké masalah','Nothing to choose.'=>'Ora ana sing bisa dipilih.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Pilih basané.','Supplementary translations'=>'Terjemahan tambahan','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Kontribusi saben komponèn kanggo suplemen domain default bareng saben locale.','Component'=>'Komponèn','Language'=>'Basa','Included in index'=>'Kalebu ing indeks','Entries'=>'Entri','Conflicting keys'=>'Kunci sing bentrok','Yes'=>'Ya','No — component inactive'=>'Ora — komponen ora aktif','No — installed version differs from the active one'=>'Ora — versi sing diinstal beda karo sing aktif','No — component removed'=>'Ora — komponen wis dicopot','No'=>'Ora','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Namung administrator jaringan sing bisa nindakake iki, amarga iki ngowahi berkas terjemahan sing dienggo bareng kabeh situs ing jaringan iki.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim ora bisa ngrampungake verifikasi situs iki (layanan ora bisa nyambung bali menyang situs). Registrasi dijeda.','This site already has an active registration that can no longer be recovered automatically.'=>'Situs iki wis nduweni registrasi aktif sing ora bisa dipulihake kanthi otomatis maneh.','Restart registration'=>'Miwiti maneh registrasi','Babilim settings'=>'Pangaturan Babilim','General'=>'Umum','Advanced'=>'Lanjutan','Languages'=>'Basa-basa','Automatic installs'=>'Instalasi otomatis','Install available translations automatically'=>'Instal terjemahan sing kasedhiya kanthi otomatis','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'Ing paket gratis, namung komponen sing wis nggunakake salah siji slot gratis sampeyan sing diinstal kanthi otomatis, dadi ora ana slot anyar sing dienggo.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Situs iki dadi bagéan saka jaringan multisitus, sing ora nginstal terjemahan anyar kanthi otomatis. Terjemahan sing wis diinstal isih dianyari.','Custom overrides'=>'Penggantian khusus','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Simpen penggantian terjemahan dhewe nalika mbusak kabeh utawa nyopot plugin iki.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Berkas terjemahan sing sampeyan selehake ing %s tansah luwih utama tinimbang sing saka Babilim. Berkas kasebut disimpen kajaba sampeyan mbusak centhange.','Uninstall'=>'Nyopot','Delete all Babilim data on uninstall'=>'Busak kabeh data Babilim nalika dicopot','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Mati kanthi baku: mbusak plugin tetep nyimpen identitas situs iki, supaya instal ulang bisa nggunakake maneh.','Account'=>'Akun','Save changes'=>'Simpen owahan','Disable Babilim'=>'Pateni Babilim','Installed translations are kept, but no further checks or downloads will run.'=>'Terjemahan sing wis diinstal tetep disimpen, nanging ora ana pamriksan utawa unduhan maneh sing bakal dijalanake.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Pateni Babilim? Terjemahan sing wis diinstal tetep disimpen, nanging ora ana pamriksan utawa unduhan maneh sing bakal dijalanake.','This site is not registered with Babilim yet.'=>'Situs iki durung didaftarake ing Babilim.','This site is already licensed. Reload the page.'=>'Situs iki wis nduweni lisensi. Muat ulang kaca.','Checkout is not available for this site right now.'=>'Checkout ora kasedhiya kanggo situs iki saiki.','Could not start checkout: %s'=>'Ora bisa miwiti checkout: %s','Babilim is not enabled.'=>'Babilim ora diaktifake.','Not registered yet'=>'Durung didaftarake','Not verified'=>'Durung diverifikasi','Verified'=>'Wis diverifikasi','Status'=>'Status','Licensed'=>'Duwe lisensi','Partner'=>'Mitra','Free'=>'Gratis','License'=>'Lisensi','Upgrade this site'=>'Tingkatake situs iki','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Pembelian sepisan kanggo situs iki: %1$s %2$s. Kalebu kabeh nganyari terjemahan ing tembe. Pembayaran ditangani dening Paddle ing tab anyar.','This issues a new restore code and the previous one stops working. Continue?'=>'Iki bakal nerbitake kode pemulihan anyar lan kode sing sadurunge ora bisa digunakake maneh. Terusake?','Show a new restore code'=>'Tampilake kode pemulihan anyar','rc_…'=>'rc_…','Restore code'=>'Kode pemulihan','Restore purchase'=>'Pulihake pembelian','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Wis tau tuku lisensi kanggo domain iki? Lebokna kode pemulihan sing sampeyan tampa nalika checkout.','That does not look like a restore code.'=>'Iki ora katon kaya kode pemulihan.','This restore code was not recognised for this site.'=>'Kode pemulihan iki ora dikenali kanggo situs iki.','Too many attempts. Try again tomorrow.'=>'Kakehan upaya. Cobanen maneh sesuk.','This site must be verified first.'=>'Situs iki kudu diverifikasi dhisik.','Could not restore the purchase: %s'=>'Ora bisa mulihake pembelian: %s','Purchase restored. This site is now licensed.'=>'Pembelian wis dipulihake. Situs iki saiki wis duwe lisensi.','This site has no purchase to show a code for.'=>'Situs iki ora duwe pembelian sing bisa dituduhake kodene.','Could not show a new restore code: %s'=>'Ora bisa nampilake kode pemulihan anyar: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Kode pemulihan anyar sampeyan: %s. Simpenen ing panggonan sing aman — kode sadurunge ora bisa digunakake maneh.','What is sent when Babilim checks this site'=>'Apa sing dikirim nalika Babilim mriksa situs iki','(detected)'=>'(kadeteksi)','No language is managed yet.'=>'Durung ana basa sing dikelola.','Babilim adds translations for every language checked here.'=>'Babilim nambahake terjemahan kanggo saben basa sing dicentang ing kene.','Add another language'=>'Tambah basa liyane','Choose a language…'=>'Pilih basa…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Ora bisa ngemot dhaptar lengkap locale WordPress.org saka layanan, mula ora ana basa liyane sing bisa ditambahake saiki.','Theme'=>'Tema','Plugin'=>'Plugin','Free quota'=>'Kuota gratis','Downloads: %1$d/%2$d (%3$s)'=>'Undhuhan: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Indeks terjemahan tambahan','Built'=>'Wis dibangun','Included'=>'Kalebu','Excluded'=>'Dikecualekake','Already in WordPress core'=>'Wis ana ing inti WordPress','Supplementary translation maintenance'=>'Pangopènan terjemahan tambahan','Maintenance status is not available right now.'=>'Status pangopènan ora kasedhiya saiki.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Pembersihan dijeda ing %1$s: %2$s. Ora ana sing dibusak.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Pembersihan pungkasan ing %1$s: %2$d anyar ditandhani, %3$d berkas dibusak, %4$d cathetan dicopot.','No cleanup has run yet.'=>'Durung ana pembersihan sing mlaku.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Panulisan indeks terjemahan bentrok karo panyuwunan liyane ing %1$s (%2$s) lan ora ditrapake; versi paling anyar disimpen.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Panulisan indeks terjemahan ing %1$s (%2$s) ora bisa rampung lan ora ditrapake (%3$s).','Maintenance'=>'Pangopènan','Rebuild index now'=>'Bangun maneh indeks saiki','Sweep now'=>'Resiki saiki','Danger zone'=>'Zona bebaya','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Mbusak saben berkas basa sing wis diinstal Babilim kanggo saben plugin lan tema ing situs iki.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Busak kabeh sing wis diinstal Babilim? Iki bakal mbusak saben berkas basa sing wis diinstal Babilim kanggo saben plugin lan tema ing situs iki.','Remove everything Babilim installed'=>'Busak kabeh sing wis diinstal Babilim','This string is too long to be sent as a report, so no report form is offered for it.'=>'String iki dawa banget kanggo dikirim minangka laporan, mula formulir laporan ora disedhiyakake.','Category'=>'Kategori','Choose a category…'=>'Pilih kategori…','Roll back and send report'=>'Kembalikan lan kirim laporan','Send report'=>'Kirim laporan','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Sawetara teks komponen iki ditulis permanen dening pangripta lan ora bisa diterjemahake nganggo paket basa.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'Kasedhiya bareng tema','Bundled with the plugin'=>'Kasedhiya bareng plugin','Upload was not accepted'=>'Unggahan ora ditampa','Upload expired before it finished'=>'Unggahan kadaluwarsa sadurunge rampung','No translation'=>'Ora ana terjemahan','Upload in progress — continue or cancel'=>'Unggahan lagi mlaku — terusake utawa batalake','Scheduled, waiting to be processed'=>'Wis dijadwalake, ngenteni diproses','Translating…'=>'Lagi nerjemahake…','Translation failed'=>'Terjemahan gagal','Free quota used'=>'Kuota gratis wis dienggo','Needs a paid license'=>'Butuh lisensi mbayar','Not supported'=>'Ora didukung','Status unknown'=>'Status ora dingerteni','translation statusInstalled'=>'Wis diinstal','Update available'=>'Ana versi anyar sing kasedhiya','Removed after a failed integrity check'=>'Dibusak sawise pemeriksaan integritas gagal','Installed · built for %s, new version scheduled'=>'Wis diinstal · digawe kanggo %s, versi anyar wis dijadwalake','Installed · built for a different version, new version scheduled'=>'Wis diinstal · digawe kanggo versi beda, versi anyar wis dijadwalake','Installed · built for %s, translating the new version…'=>'Wis diinstal · digawe kanggo %s, lagi nerjemahake versi anyar…','Installed · built for a different version, translating the new version…'=>'Wis diinstal · digawe kanggo versi beda, lagi nerjemahake versi anyar…','Installed · built for %1$s, this site has %2$s'=>'Wis diinstal · digawe kanggo %1$s, situs iki nganggo %2$s','Installed · built for %s'=>'Wis diinstal · digawe kanggo %s','Installed · built for a different version'=>'Wis diinstal · digawe kanggo versi beda','Installed · built for %s, new version failed'=>'Wis dipasang · dibangun kanggo %s, versi anyar gagal','Installed · built for a different version, new version failed'=>'Wis dipasang · dibangun kanggo versi sing beda, versi anyar gagal','Installed · built for %s, new version needs a paid license'=>'Wis dipasang · dibangun kanggo %s, versi anyar mbutuhake lisensi mbayar','Installed · built for a different version, new version needs a paid license'=>'Wis dipasang · dibangun kanggo versi sing beda, versi anyar mbutuhake lisensi mbayar','Installed · built for %s, free quota used'=>'Wis dipasang · dibangun kanggo %s, kuota gratis wis entek','Installed · built for a different version, free quota used'=>'Wis dipasang · dibangun kanggo versi sing beda, kuota gratis wis entek','translation statusAvailable'=>'Kasedhiya','Installed · %s'=>'Wis dipasang · %s','Available · %s'=>'Kasedhiya · %s','Update'=>'Nganyari','Download'=>'Undhuh','Updating…'=>'Nganyari…','Downloading…'=>'Ngundhuh…','Retry request'=>'Coba njaluk maneh','Request newer translation'=>'Njaluk terjemahan sing luwih anyar','Request translation'=>'Njaluk terjemahan','Requesting…'=>'Njaluk…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'Njaluk terjemahan bakal nggunakake siji slot gratis, kajaba komponen iki wis nggunakake siji. Terjemahan sing gagal ora mbalekake slot kasebut.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'Yen komponen iki durung nggunakake siji slot gratis, njaluk terjemahan bakal nggunakake siji. Terjemahan sing gagal ora mbalekake slot kasebut. Terusake?','No plugins or themes found.'=>'Ora ana plugin utawa tema sing ditemokake.','Clear filters'=>'Busak filter','No components match these filters. %s'=>'Ora ana komponen sing cocog karo filter iki. %s','Select all'=>'Pilih kabeh','All'=>'Kabeh','Available'=>'Kasedhiya','Updates'=>'Pembaruan','Requestable'=>'Bisa dijaluk','Installed'=>'Wis dipasang','Plugins'=>'Plugin','Themes'=>'Tema','All languages'=>'Kabeh basa','Language:'=>'Basa:','Bulk actions apply to every matching language of each selected component.'=>'Tindakan massal ditrapake kanggo saben basa sing cocog saka saben komponen sing dipilih.','Bulk actions apply only to the selected language of each selected component.'=>'Tindakan massal mung ditrapake kanggo basa sing dipilih saka saben komponen sing dipilih.','Version %s'=>'Versi %s','Theme · %s'=>'Tema · %s','Plugin · %s'=>'Plugin · %s','Remove the %2$s translation of %1$s from this site?'=>'Busak terjemahan %2$s saka %1$s saka situs iki?','Roll back the %2$s translation of %1$s to the previous build?'=>'Kembalikan terjemahan %2$s saka %1$s menyang build sakdurunge?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'Tantangan registrasi ora ana ing wujud sing dikarepake.','That is not a valid build identifier.'=>'Iku dudu identifier build sing sah.','Refusing to write outside the Babilim language-file directory.'=>'Ora gelem nulis ing njaban Direktori berkas basa Babilim.','Could not write the downloaded package to disk.'=>'Ora bisa nulis paket sing wis diundhuh menyang disk.','Unexpected HTTP %d response.'=>'Respons HTTP %d sing ora dikarepake.','This site\'s URL, so the service can verify you own it.'=>'URL situs iki, supaya layanan bisa mbuktekake yen sampeyan sing duwe.','Your WordPress version, to serve compatible translation files.'=>'Versi WordPress sampeyan, kanggo nyedhiyakake berkas terjemahan sing cocog.','Your PHP version, for compatibility.'=>'Versi PHP sampeyan, kanggo kompatibilitas.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Versi plugin iki dhewe, supaya layanan bisa ngandhani sampeyan kanggo nganyari yen wis kadaluwarsa banget kanggo komunikasi.','This site\'s configured locale.'=>'Locale sing dikonfigurasi ing situs iki.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Saben locale sing digunakake ing situs iki (locale situs, paket basa sing wis diinstal, locale pangguna, lan sing sampeyan tambahake kanthi manual). Ora ana locale sing dianggep beda saka liyane.','(a public key generated for this site)'=>'(kunci publik sing digawe kanggo situs iki)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Kunci publik instalasi situs iki, digunakake kanggo mbuktekake yen panyuwunan pancen teka saka situs iki. Mung separo publik sing tau dikirim.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Saben plugin/tema sing diinstal: slug, versi, text domain, apa iku daftar wp.org, locale bawaan dhewe, lan locale endi sing wis sampeyan instal terjemahan Babilim.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'Mung nalika sampeyan ngonfirmasi unggahan kanggo plugin utawa tema sing ora ana ing WordPress.org: kabeh direktori komponen kasebut, minangka zip.','(generic codes and coordinates only)'=>'(mung kode umum lan koordinat)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Nganti 20 kajadian diagnostik sing isih ngenteni (kayata berkas sing gagal pemeriksaan integritas), saben mung arupa kode, komponen, lan locale, lan ora tau isi string utawa teks terjemahan.','Unsafe locale: %s'=>'Locale ora aman: %s','Manifest unavailable: %s'=>'Manifest ora kasedhiya: %s','Could not determine active components; the existing merged index was left unchanged.'=>'Ora bisa nemtokake komponen aktif; indeks gabungan sing ana ora diowahi.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Ora bisa nemtokake plugin/tema sing diinstal; resiki dilewati, ora ana sing dibusak.','Sweep aborted without orphaning anything: %s.'=>'Proses reresik dibatalake tanpa njalari berkas utawa data apa wae kelangan sesambungane: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Pembersihan wis mlaku, nanging sawetara owahane ora bisa dicathet ing indeks terjemahan; pembersihan sabanjure bakal nyoba maneh.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Indeks gabungan kanggo \'%s\' wis dibangun maneh, nanging indeks terjemahan ora bisa nyathet; pambangunan maneh sabanjure bakal nyoba maneh.','Could not write the staged merged index.'=>'Ora bisa nulis indeks gabungan sing disiapake.','Re-parsed entry count did not match the built index.'=>'Jumlah entri sing diurai maneh ora cocog karo indeks sing dibangun.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Ora bisa mindhahake indeks gabungan kanggo \'%s\' menyang panggonane; indeks sing disajikake sadurunge (yen ana) wis dibusak tinimbang ditinggal separo dianyari. Ora ana suplemen domain default sing disajikake kanggo locale iki nganti pambangunan maneh sing sabanjure kasil.','Could not open zip: %s'=>'Ora bisa mbukak zip: %s','Zip has no manifest.json.'=>'Zip ora duwe manifest.json.','manifest.json in the zip is not valid JSON.'=>'manifest.json ing zip ora JSON sing sah.','manifest.json\'s \'%s\' does not match the expected value.'=>'\'%s\' ing manifest.json ora cocog karo nilai sing dikarepake.','Another installation is running; try again in a moment.'=>'Ana instalasi liyane sing lagi mlaku; coba maneh sedhela.','Not a valid server_build_id: %s'=>'Dudu server_build_id sing sah: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Kind \'%1$s\' ing manifest paket ora cocog karo kind sing dijaluk \'%2$s\'.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Text domain paket \'%1$s\' ora cocog karo salinan komponen ing situs iki (\'%2$s\'), mula ora diinstal.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Domain sing diwenehake \'%1$s\' ora cocog karo slug manifest paket \'%2$s\' lan uga text_domain \'%3$s\'.','Unsafe slug: %s'=>'Slug ora aman: %s','Unsafe text_domain: %s'=>'text_domain ora aman: %s','The package has no %s for its own text domain.'=>'Paket iki ora duwe %s kanggo text domain dhewe.','manifest.json is missing or has an invalid \'%s\'.'=>'Kolom \'%s\' ing manifest.json ora ana utawa ora valid.','manifest.json is missing or has an invalid \'entries\'.'=>'Kolom \'entries\' ing manifest.json ora ana utawa ora valid.','manifest.json is missing or has an invalid \'files\'.'=>'Kolom \'files\' ing manifest.json ora ana utawa ora valid.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'Kolom \'extra_domains\' ing manifest.json ora ana utawa ora valid.','manifest.json is missing or has an invalid \'build_no\'.'=>'Kolom \'build_no\' ing manifest.json ora ana utawa ora valid.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' ing manifest.json dudu build id sing valid.','manifest.json\'s \'contract\' is not a valid version string.'=>'\'contract\' ing manifest.json dudu string versi sing valid.','manifest.json\'s \'status\' must be \'published\'.'=>'\'status\' ing manifest.json kudu \'published\'.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'\'kind\' ing manifest.json kudu \'plugin\' utawa \'theme\'.','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json nduwe \'default_domain_entries\' sing ora valid.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json nduwe \'default_domain_files\' sing ora valid.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest ora ana utawa nduwe \'%s\' sing ora valid.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' ing expected_manifest dudu build id sing valid.','No record for %s'=>'Ora ana cathetan kanggo %s','One or more served files no longer match the manifest.'=>'Siji utawa luwih berkas sing disajikake wis ora cocog karo manifest.','No previous build to roll back to.'=>'Ora ana build sakdurunge kanggo dikembalikan.','The change could not be recorded in the translation index; please try again.'=>'Owah-owahan ora bisa dicathet ing indeks terjemahan; coba maneh.','Unknown kind: %s'=>'Kind ora dikenal: %s','Unsafe domain: %s'=>'Domain ora aman: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Text domain \'%1$s\' (%2$s) wis disajikake kanggo komponen liyane sing wis diinstal (%3$s); ora ana sing diinstal.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Pangembalian bakal nimpa \'%1$s\' (%2$s), sing saiki disajikake kanggo komponen liyane sing wis diinstal (%3$s); ora ana sing diowahi.','Zip is missing expected file: %s'=>'Zip ora ana berkas sing dikarepake: %s','sha256 mismatch for %s'=>'sha256 ora cocog kanggo %s','The package declares no main translation file.'=>'Paket ora nyatakake berkas terjemahan utama.','Zip is missing expected default file: %s'=>'Zip ora ana berkas default sing dikarepake: %s','sha256 mismatch for default/%s'=>'sha256 ora cocog kanggo default/%s','Could not stage %s'=>'Ora bisa nyiapake (stage) %s','Could not stage default/%s'=>'Ora bisa nyiapake (stage) default/%s','Entry count mismatch for %s'=>'Jumlah entri ora cocog kanggo %s','Could not verify entry count for %s'=>'Ora bisa verifikasi jumlah entri kanggo %s','l10n.php entry count mismatch for %s'=>'Jumlah entri l10n.php ora cocog kanggo %s','Default supplement entry count mismatch.'=>'Jumlah entri suplemen default ora cocog.','The package produced no servable main translation file.'=>'Paket ora ngasilake berkas terjemahan utama sing bisa disajikake.','Could not prepare %s for rollback.'=>'Ora bisa nyiapake %s kanggo dikembalikan.','Could not back up %s before replacing it.'=>'Ora bisa nggawe serep %s sadurunge diganti.','Could not move %s into place.'=>'Ora bisa mindhah %s menyang panggonane.','English (United States)'=>'Inggris (Amerika Serikat)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest ora kasedhiya: %s','could not read _manifest.json: %s'=>'ora bisa maca _manifest.json: %s','failed to parse _manifest.json: %s'=>'gagal ngurai _manifest.json: %s','_manifest.json has an unexpected structure'=>'_manifest.json nduweni struktur sing ora dikarepake','Could not create the package archive.'=>'Arsip paket ora bisa digawe.','No writable temporary directory is available for packaging.'=>'Ora ana direktori sementara sing bisa ditulis kanggo nggawe paket.','A file in the component could not be read, so it was not packaged.'=>'Ana berkas ing komponen sing ora bisa diwaca, mula ora dipaketake.','Only plugins and themes can be packaged.'=>'Namung plugin lan tema sing bisa dipaketake.','The component\'s main file was not found.'=>'Berkas utama komponen ora ditemokake.','The component is not inside the plugins or themes directory.'=>'Komponen iki ora ana ing direktori plugin utawa tema.','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim kehabisan wektu kanggo langkah iki lan bakal nerusake ing pengecekan sabanjure.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim ora bisa verifikasi situs iki, mula ora ana sing diundhuh utawa dipasang nganti verifikasi kasil.','Registration response was missing required fields.'=>'Wangsulan registrasi kekurangan kolom sing dibutuhake.','No pending challenge to verify.'=>'Ora ana tantangan sing nunggu verifikasi.','Verify response was missing site_token.'=>'Wangsulan verifikasi ora ana site_token.','No site id is on file to rotate a token for.'=>'Ora ana ID situs sing kasimpen kanggo ngrotasi token.','Rotate-token response was missing site_token.'=>'Wangsulan rotate-token ora ana site_token.','nonce must be a hexadecimal string.'=>'nonce kudu awujud string heksadesimal.','No pending challenge for this nonce.'=>'Ora ana tantangan sing nunggu kanggo nonce iki.','Too many requests.'=>'Panyuwunan kakehan.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Situs iki nduweni %1$d komponen ing %2$d basa, sing mbutuhake %3$d batch pengecekan; Babilim mung bisa nangani paling akeh %4$d saben proses. Kurangi basa sing dikelola ing Setelan utawa nonaktifake plugin lan tema sing ora dienggo, banjur pencet Priksa maneh saiki.','Babilim could not finish checking this site.'=>'Babilim ora bisa ngrampungake pengecekan situs iki.','This site\'s address is too long for Babilim to register.'=>'Alamat situs iki dawa banget kanggo diregistrasi dening Babilim.','This site\'s locale code is not one Babilim can register.'=>'Kode locale situs iki dudu kode sing bisa diregistrasi dening Babilim.','The download response was missing a usable location.'=>'Wangsulan undhuhan ora ana lokasi sing bisa digunakake.','The service\'s upload offer was incomplete.'=>'Tawaran unggah saka layanan ora lengkap.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Komponen iki luwih gedhe tinimbang sing ditampa layanan, mula ora bisa diunggah.','The packaged component could not be read.'=>'Komponen sing wis dipaketake ora bisa diwaca.','A part of the upload kept failing, so the upload was cancelled.'=>'Salah siji bagean unggahan terus gagal, mula unggahan dibatalake.','Could not read: %s'=>'Ora bisa diwaca: %s']];